function hash(text:string):number {
  let value=2166136261;
  for(let i=0;i<text.length;i++)value=Math.imul(value^text.charCodeAt(i),16777619);
  return value>>>0;
}
function slug(text:string):string {
  return text.replace(/[øØ]/g,"o").replace(/ß/g,"ss").normalize("NFKD").replace(/[\u0300-\u036f]/g,"").toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
}
const clamp=(n:number,min=1,max=99)=>Math.max(min,Math.min(max,Math.round(n)));
const KEYS:(keyof FootballAttributes)[]=["pac","sho","pas","dri","def","phy"];
const BASE:Record<FootballPosition,number[]>={
  GK:[45,20,52,37,20,65], CB:[60,35,57,50,75,77],
  LB:[74,44,64,65,65,66], RB:[74,44,64,65,65,66],
  DM:[61,50,72,62,70,70], CM:[64,62,75,70,52,63],
  AM:[70,67,75,76,34,56], LW:[79,67,65,77,27,53],
  RW:[79,67,65,77,27,53], ST:[73,77,52,66,25,70],
};
const WEIGHTS:Record<FootballPosition,number[]>={
  GK:[10,0,20,5,10,55], CB:[10,2,12,8,43,25],
  LB:[20,3,20,15,27,15], RB:[20,3,20,15,27,15],
  DM:[10,5,25,15,30,15], CM:[10,12,32,25,11,10],
  AM:[12,22,28,28,3,7], LW:[26,22,18,26,2,6],
  RW:[26,22,18,26,2,6], ST:[20,42,8,20,2,8],
};
/** Original balance profiles, deterministically generated and pinned by version. */
function profile(id:string,position:FootballPosition,target:number):FootballAttributes {
  const values=BASE[position].map((n,i)=>n+(hash(`${id}:${i}`)%9)-4);
  if(position!=="GK"){
    const ovr=values.reduce((s,n,i)=>s+n*WEIGHTS[position][i],0)/100;
    for(let i=0;i<values.length;i++)values[i]=clamp(values[i]+target-ovr);
  }
  return Object.fromEntries(KEYS.map((key,i)=>[key,clamp(values[i])])) as FootballAttributes;
}
function keeperProfile(id:string,target:number):FootballGoalkeeperAttributes {
  const values=[target+1,target-1,target-5,target+3,target-24,target+1].map((n,i)=>clamp(n+(hash(`${id}:gk:${i}`)%7)-3));
  // Calibrate to the same original GK OVR weights used by player development.
  const weights=[20,20,10,25,5,20];
  const ovr=values.reduce((s,n,i)=>s+n*weights[i],0)/100;
  return Object.fromEntries(["diving","handling","kicking","reflexes","speed","positioning"].map((key,i)=>[key,clamp(values[i]+target-ovr)])) as FootballGoalkeeperAttributes;
}
const CLUB_MAP=new Map(CLUB_FACTS.map(c=>[c.id,c]));

function realPlayer(fact:PlayerFact):FootballRosterPlayer {
  const [clubId,name,number,nationality,officialPositionGroup,position,homegrown,registration,loanedOut,ageAtSnapshot,uefaList,sourceIdentity,sourceOverride]=fact;
  const club=CLUB_MAP.get(clubId)!;
  const id=`real-${sourceIdentity??slug(name)}`;
  const h=hash(id);
  // These are authored GAME values, not ratings of a real person's ability.
  const youth=registration==="under21"||registration==="uefa-b";
  const target=clamp(club.prestige-5+(h%11)-(youth?12:0),55,91);
  const simulatedBirthYear=ageAtSnapshot!==null?2026-ageAtSnapshot:youth?2007+h%3:1992+h%14;
  return {
    id,name,clubId,position,number,nationality,officialPositionGroup,fictional:false,
    attributes:profile(id,position,target),
    ...(position==="GK"?{goalkeeper:keeperProfile(id,target)}:{}),
    simulatedBirthYear,potential:clamp(target+(youth?12:4)+(h%7),target,96),
    preferredFoot:h%20===0?"both":h%4===0?"left":"right",
    weeklyWage:Math.round((Math.max(20,target-45)**2)*(youth?14:32)/500)*500,
    contractUntil:`${2027+h%4}-06-30`,
    transferValue:Math.round((target-45)**3*(youth?750:500)/50000)*50000,
    homegrown,registration:registration??"unverified",loanedOut,source:sourceOverride??club.source,
    ...(ageAtSnapshot!==null?{ageAtSnapshot,ageVerifiedOn:FOOTBALL_DATA_VERIFIED_ON}:{}),
    ...(uefaList?{uefaRegistration:{season:"2026/27" as const,list:uefaList,source:club.source,...(club.source.includes("/uefaeuropaleague/")?{competition:"europa-league" as const}:{})}}:{}),
    ...(sourceIdentity?{sourceIdentity}:{}),
  };
}

export const FOOTBALL_CLUBS:readonly FootballClub[]=CLUB_FACTS;
export const PREMIER_LEAGUE_CLUBS:readonly FootballClub[]=FOOTBALL_CLUBS.filter(c=>c.league==="premier-league");
export const BACKGROUND_ENGLISH_CLUB_IDS:readonly string[]=FOOTBALL_CLUBS.filter(c=>c.country==="ENG"&&c.league==="background").map(c=>c.id);
export const CHAMPIONS_LEAGUE_CLUB_IDS:readonly string[]=FOOTBALL_CLUBS.filter(c=>c.championsLeague).sort((a,b)=>(a.pot??4)-(b.pot??4)||a.name.localeCompare(b.name,"en")).map(c=>c.id);
export const FOOTBALL_PLAYERS:readonly FootballRosterPlayer[]=PLAYER_FACTS.map(realPlayer);
const PLAYER_MAP=new Map(FOOTBALL_PLAYERS.map(p=>[p.id,p]));
export function footballClub(id:string):FootballClub|undefined {return CLUB_MAP.get(id);}
export function footballPlayer(id:string):FootballRosterPlayer|undefined {return PLAYER_MAP.get(id);}
export function footballClubSquad(clubId:string,{includeUnavailable=false}:{includeUnavailable?:boolean}={}):FootballRosterPlayer[]{
  return FOOTBALL_PLAYERS.filter(p=>p.clubId===clubId&&(includeUnavailable||(!p.loanedOut&&p.registration!=="unverified")));
}
/** Copy once on career creation; never silently reseed a populated save. */
export function createFootballWorldRoster():FootballWorldRoster {
  return structuredClone({rosterVersion:FOOTBALL_ROSTER_VERSION,balanceVersion:FOOTBALL_BALANCE_VERSION,clubs:[...FOOTBALL_CLUBS],players:[...FOOTBALL_PLAYERS]});
}
